-- 0001_foundation.sql
-- Foundation objects shared by every module. Module tables are added by their own
-- migrations (0002+), so this file must stay dependency-free.
--
-- Conventions used across the schema:
--   * every table lives in a module schema, never in "public";
--   * primary keys are uuid v7 generated by the application, so rows sort by time;
--   * timestamps are timestamptz and always UTC;
--   * money is stored as integer minor units plus an ISO-4217 code (never numeric/float);
--   * nothing is hard-deleted: rows carry deleted_at, and the ledger is append-only.

CREATE EXTENSION IF NOT EXISTS pgcrypto;   -- gen_random_uuid(), digest()
CREATE EXTENSION IF NOT EXISTS citext;     -- case-insensitive handles and emails

CREATE SCHEMA IF NOT EXISTS ops;
CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS verify;
CREATE SCHEMA IF NOT EXISTS catalog;
CREATE SCHEMA IF NOT EXISTS content;
CREATE SCHEMA IF NOT EXISTS media;
CREATE SCHEMA IF NOT EXISTS subs;
CREATE SCHEMA IF NOT EXISTS billing;
CREATE SCHEMA IF NOT EXISTS ledger;
CREATE SCHEMA IF NOT EXISTS payouts;
CREATE SCHEMA IF NOT EXISTS msg;
CREATE SCHEMA IF NOT EXISTS safety;
CREATE SCHEMA IF NOT EXISTS notify;

-- ---------------------------------------------------------------------------
-- Shared trigger: maintain updated_at without trusting the application layer.
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION ops.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- ---------------------------------------------------------------------------
-- Append-only, hash-chained audit log for privileged actions.
--
-- Each row hashes the previous row's hash together with its own content, so any
-- deletion or edit of history breaks the chain and is detectable by
-- ops.verify_audit_chain(). Writes go through ops.append_audit() only; the table
-- rejects UPDATE and DELETE outright.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ops.audit_log (
    id           bigserial   PRIMARY KEY,
    occurred_at  timestamptz NOT NULL DEFAULT now(),
    actor_type   text        NOT NULL CHECK (actor_type IN ('user', 'staff', 'service', 'system')),
    actor_id     text        NOT NULL,
    action       text        NOT NULL,
    target_type  text        NOT NULL,
    target_id    text        NOT NULL,
    reason       text,
    metadata     jsonb       NOT NULL DEFAULT '{}'::jsonb,
    request_id   text,
    prev_hash    text,
    hash         text        NOT NULL
);

CREATE INDEX IF NOT EXISTS audit_log_target_idx ON ops.audit_log (target_type, target_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS audit_log_actor_idx  ON ops.audit_log (actor_type, actor_id, occurred_at DESC);

CREATE OR REPLACE FUNCTION ops.audit_log_immutable() RETURNS trigger
    LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'ops.audit_log is append-only';
END;
$$;

DROP TRIGGER IF EXISTS audit_log_no_update ON ops.audit_log;
CREATE TRIGGER audit_log_no_update
    BEFORE UPDATE OR DELETE ON ops.audit_log
    FOR EACH ROW EXECUTE FUNCTION ops.audit_log_immutable();

CREATE OR REPLACE FUNCTION ops.append_audit(
    p_actor_type  text,
    p_actor_id    text,
    p_action      text,
    p_target_type text,
    p_target_id   text,
    p_reason      text DEFAULT NULL,
    p_metadata    jsonb DEFAULT '{}'::jsonb,
    p_request_id  text DEFAULT NULL
) RETURNS text
    LANGUAGE plpgsql
AS $$
DECLARE
    v_prev text;
    v_hash text;
BEGIN
    -- Serialise appends so two concurrent writers cannot both extend the same
    -- predecessor and fork the chain.
    SELECT hash INTO v_prev FROM ops.audit_log ORDER BY id DESC LIMIT 1 FOR UPDATE;
    PERFORM pg_advisory_xact_lock(hashtext('ops.audit_log'));

    v_hash := encode(digest(
        coalesce(v_prev, '') || '|' ||
        p_actor_type || '|' || p_actor_id || '|' || p_action || '|' ||
        p_target_type || '|' || p_target_id || '|' ||
        coalesce(p_reason, '') || '|' || p_metadata::text || '|' || coalesce(p_request_id, ''),
        'sha256'), 'hex');

    INSERT INTO ops.audit_log (
        actor_type, actor_id, action, target_type, target_id,
        reason, metadata, request_id, prev_hash, hash
    ) VALUES (
        p_actor_type, p_actor_id, p_action, p_target_type, p_target_id,
        p_reason, coalesce(p_metadata, '{}'::jsonb), p_request_id, v_prev, v_hash
    );

    RETURN v_hash;
END;
$$;

-- Returns the id of the first row whose stored hash does not match its content,
-- or NULL when the chain is intact. Used by a scheduled integrity job.
CREATE OR REPLACE FUNCTION ops.verify_audit_chain()
    RETURNS bigint
    LANGUAGE plpgsql
AS $$
DECLARE
    r          record;
    v_prev     text := NULL;
    v_expected text;
BEGIN
    FOR r IN SELECT * FROM ops.audit_log ORDER BY id LOOP
        v_expected := encode(digest(
            coalesce(v_prev, '') || '|' ||
            r.actor_type || '|' || r.actor_id || '|' || r.action || '|' ||
            r.target_type || '|' || r.target_id || '|' ||
            coalesce(r.reason, '') || '|' || r.metadata::text || '|' || coalesce(r.request_id, ''),
            'sha256'), 'hex');
        IF v_expected <> r.hash OR coalesce(r.prev_hash, '') <> coalesce(v_prev, '') THEN
            RETURN r.id;
        END IF;
        v_prev := r.hash;
    END LOOP;
    RETURN NULL;
END;
$$;

-- ---------------------------------------------------------------------------
-- Outbox: every domain event is written in the same transaction as its state
-- change and published afterwards by a worker. No side effect escapes a
-- committed transaction.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ops.outbox (
    id             bigserial   PRIMARY KEY,
    topic          text        NOT NULL,
    payload        jsonb       NOT NULL,
    headers        jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at     timestamptz NOT NULL DEFAULT now(),
    available_at   timestamptz NOT NULL DEFAULT now(),
    published_at   timestamptz,
    attempts       integer     NOT NULL DEFAULT 0,
    last_error     text
);

CREATE INDEX IF NOT EXISTS outbox_unpublished_idx
    ON ops.outbox (available_at)
    WHERE published_at IS NULL;

-- ---------------------------------------------------------------------------
-- Feature flags and immutable-ish runtime configuration, changed by PR only.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ops.feature_flags (
    key         text        PRIMARY KEY,
    enabled     boolean     NOT NULL DEFAULT false,
    description text        NOT NULL DEFAULT '',
    rollout     jsonb       NOT NULL DEFAULT '{}'::jsonb,
    updated_at  timestamptz NOT NULL DEFAULT now(),
    updated_by  text        NOT NULL DEFAULT 'system'
);

DROP TRIGGER IF EXISTS feature_flags_updated_at ON ops.feature_flags;
CREATE TRIGGER feature_flags_updated_at
    BEFORE UPDATE ON ops.feature_flags
    FOR EACH ROW EXECUTE FUNCTION ops.set_updated_at();

